  if (typeof s !== 'string' || s.trim() === '') {
    throw new Error('parseRange: input must be a non-empty string');
  }

  const numbers = [];
  for (const rawToken of s.split(',')) {
    const token = rawToken.trim();
    if (token === '') {
      throw new Error('parseRange: empty token');
    }

    const parts = token.split('-').map((p) => p.trim());
    if (parts.length === 1) {
      numbers.push(parseNonNegativeInt(parts[0]));
    } else if (parts.length === 2) {
      const a = parseNonNegativeInt(parts[0]);
      const b = parseNonNegativeInt(parts[1]);
      if (a > b) {
        throw new Error('parseRange: reversed range');
      }
      for (let i = a; i <= b; i++) {
        numbers.push(i);
      }
    } else {
      throw new Error('parseRange: malformed token');
    }
  }

  return [...new Set(numbers)].sort((a, b) => a - b);
}

